head.script:
scwin.trigger1_onclick = function(e) {
    tabCon1.disableTab(0);
    tabCon1.disableTab(1);
};
scwin.trigger2_onclick = function(e) {
    tabCon1.enableTab(0);
    tabCon1.enableTab(1);
};
scwin.checkValue = function() {
    if (WebSquare.wUnit.getJq('#ip2').length == 0) {
        return WebSquare.wUnit.getObjById('tabCon1_contents_content2_body_ip2').getAttribute('disabled')
    } else {
        return ip2.getAttribute('disabled')
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabCon1').setActiveTab(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. tab Disable 된다.
    //3. The tab is disabled.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabCon1_contents_content1_body').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabCon1_contents_content2_body').getAttribute('disabled')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. enableTab 버튼을 클릭한다.
    //Click the enableTab button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. tab Enable 된다. (그전버전에서는 2. 2. EnableTab 그림처럼 inputBox 가 활성화되는 현상이 발생함.)
    // Enable the tab. (In the previous version, inputBox is activated as shown in 2. 2. EnableTab.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabCon1_contents_content1_body').getAttribute('disabled')", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabCon1_contents_content2_body').getAttribute('disabled')", "false");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
